-- =====================================================================
-- 0865_dictionary_ids_auto_increment.sql
-- Chuyển các PK của dictionary sang GENERATED BY DEFAULT AS IDENTITY
-- + Bổ sung unique indexes phục vụ upsert/idempotency
-- Bảng ảnh hưởng:
--   - dict_entries(entry_id)
--   - dict_forms(form_id)
--   - dict_senses(sense_id)
--   - dict_examples(example_id)
--   - dict_relations(relation_id)
-- =====================================================================

SET search_path = public;

-- Helper DO block: convert column to IDENTITY if not already
-- - Nếu đang dùng SERIAL (default nextval) thì DROP DEFAULT rồi ADD IDENTITY
-- - Nếu đã là IDENTITY thì bỏ qua
-- - Nếu cột không tồn tại, bỏ qua (no-op)
CREATE OR REPLACE FUNCTION __ensure_identity(p_table text, p_column text) RETURNS void AS $$
DECLARE
v_default     text;
  v_is_identity text;
  v_exists      boolean;
BEGIN
SELECT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name   = p_table
      AND column_name  = p_column
) INTO v_exists;

IF NOT v_exists THEN
    RAISE NOTICE '[dictionary ids] Column %.% not found, skip.', p_table, p_column;
    RETURN;
END IF;

SELECT column_default, is_identity
INTO v_default, v_is_identity
FROM information_schema.columns
WHERE table_schema = 'public'
  AND table_name   = p_table
  AND column_name  = p_column;

IF v_is_identity = 'YES' THEN
    RAISE NOTICE '[dictionary ids] %.% already IDENTITY, skip.', p_table, p_column;
    RETURN;
END IF;

  -- Nếu đang có default nextval (kiểu SERIAL) thì drop trước
  IF v_default IS NOT NULL THEN
    EXECUTE format('ALTER TABLE %I ALTER COLUMN %I DROP DEFAULT', p_table, p_column);
END IF;

  -- Thêm IDENTITY
EXECUTE format('ALTER TABLE %I ALTER COLUMN %I ADD GENERATED BY DEFAULT AS IDENTITY', p_table, p_column);

RAISE NOTICE '[dictionary ids] Converted %.% to IDENTITY.', p_table, p_column;
END;
$$ LANGUAGE plpgsql;

BEGIN;

-- =======================
-- 1) Convert các PK sang IDENTITY
-- =======================
SELECT __ensure_identity('dict_entries',  'entry_id');
SELECT __ensure_identity('dict_forms',    'form_id');
SELECT __ensure_identity('dict_senses',   'sense_id');
SELECT __ensure_identity('dict_examples', 'example_id');
SELECT __ensure_identity('dict_relations','relation_id');

-- (Tuỳ chọn) đảm bảo NOT NULL cho các PK (thường đã có do PK)
ALTER TABLE IF EXISTS dict_entries   ALTER COLUMN entry_id   SET NOT NULL;
ALTER TABLE IF EXISTS dict_forms     ALTER COLUMN form_id    SET NOT NULL;
ALTER TABLE IF EXISTS dict_senses    ALTER COLUMN sense_id   SET NOT NULL;
ALTER TABLE IF EXISTS dict_examples  ALTER COLUMN example_id SET NOT NULL;
ALTER TABLE IF EXISTS dict_relations ALTER COLUMN relation_id SET NOT NULL;

-- (Tuỳ chọn) Đảm bảo PK tồn tại (thường đã có sẵn từ schema cũ)
-- Lưu ý: PostgreSQL không hỗ trợ IF NOT EXISTS cho ADD CONSTRAINT trực tiếp.
-- Có thể bỏ qua nếu đã tạo PK trong các migration trước đó.

-- =======================
-- 2) Unique indexes hỗ trợ upsert/idempotency
-- =======================
-- Entry: mỗi (lang, headword) duy nhất
CREATE UNIQUE INDEX IF NOT EXISTS uq_dict_entries_lang_headword
    ON dict_entries (lang, headword);

-- Form: mỗi (entry_id, form) duy nhất
CREATE UNIQUE INDEX IF NOT EXISTS uq_dict_forms_entry_form
    ON dict_forms (entry_id, form);

-- Sense: mỗi (entry_id, "order") duy nhất
CREATE UNIQUE INDEX IF NOT EXISTS uq_dict_senses_entry_order
    ON dict_senses (entry_id, "order");

-- Example: mỗi (sense_id, example) duy nhất
CREATE UNIQUE INDEX IF NOT EXISTS uq_dict_examples_sense_example
    ON dict_examples (sense_id, example);

-- Relation: mỗi (from_entry_id, to_entry_id, kind) duy nhất
CREATE UNIQUE INDEX IF NOT EXISTS uq_dict_relations_from_to_kind
    ON dict_relations (from_entry_id, to_entry_id, kind);

COMMIT;

-- Dọn helper function (tuỳ chọn)
DROP FUNCTION IF EXISTS __ensure_identity(text, text);
